Section CANSEC1. Context {rc : runConstT}.
Section X4S2.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32) (m0 : fmem).
  Variables (DST dcap SS DT mtl tl lo : Z) (src : list Z) (cells : list deltX1) (cbs : list byte).
  Notation SP := (bv_unsigned sp).
  Notation n := (zlen src).
  Hypothesis TOK : x1_table_ok cells tl.
  Hypothesis ECB : cbs = firstn (Z.to_nat (2 * 2^tl)) (x1_bytes' cells).
  Hypothesis LCB : zlen cbs = 2 * 2^tl.
  Hypothesis MTL : 1 <= mtl <= 12.
  Hypothesis TLM : tl <= mtl + 1.
  Hypothesis D0 : 0 <= DST.
  Hypothesis DP : 0 < dcap -> 8 <= DST.
  Hypothesis DC : 0 <= dcap < 2^32.
  Hypothesis DL : DST + dcap <= lo.
  Hypothesis S0 : 16 <= SS.
  Hypothesis SL : SS + n <= lo.
  Hypothesis NSM : n < 2^26.
  Hypothesis BYS : Forall (fun c => 0 <= c < 256) src.
  Hypothesis DT0 : 0 < DT.
  Hypothesis CBL : DT + 4 + 2 * 2^tl <= lo.
  Hypothesis DJ1 : DT + 4 + 2 * 2^tl <= DST \/ DST + dcap <= DT.
  Hypothesis DJ3 : DST + dcap <= SS \/ SS + n <= DST.
  Hypothesis LOS : lo <= SP - 4096.
  Hypothesis SP16 : SP mod 16 = 0.
  Hypothesis SP47 : SP <= 2^47.

  Notation POST := (huf_dec_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc DST dcap lo m0).
  Notation XB l := (l ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m0 DST dcap SS DT mtl tl lo src cells cbs
                      TOK ECB LCB MTL TLM D0 DP DC DL S0 SL NSM BYS DT0 CBL DJ1 DJ3 LOS SP16 SP47) (only parsing).
  Notation X4F' mm spl bd4 := (X4F ra sp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 m0 DST dcap SS DT lo src cbs mm spl bd4).

  Variables (L1 L2 L3 L4 SEG Q2 Q3 : Z).
  Notation O2 := (6 + L1). Notation O3 := (6 + L1 + L2). Notation O4 := (6 + L1 + L2 + L3).
  Hypothesis HL : 1 <= L1 /\ 1 <= L2 /\ 1 <= L3 /\ 1 <= L4 /\ 6 + L1 + L2 + L3 + L4 <= n.
  Hypothesis HQ : 0 < SEG <= Q2 /\ Q2 <= Q3 /\ Q3 <= dcap /\ 4 <= dcap.
  Notation A3 l := (XB l L1 L2 L3 L4 SEG Q2 Q3 HL HQ) (only parsing).

  (* [comment removed for export] *)
  Lemma x4s2_chk : forall q1 q2 q3 q4 pt1 pt2 pt3 pt4 bits1 bits3 v32 v48 v152 c4 bc4 mm j0 j72 j88 j104 jp
                          (xra t1 t2 a1 a4 a6 x19 x26 x27 t3 t4 t5 t6 : word),
    X4F' mm (SPL3 (DST + dcap) v32 (tl + 256 * mtl) v48 (DST + Q3) (SS + O3) (DST + Q2) dcap (DST + dcap - 3) (SS + 14)
                  (SS + O2 + 8) (SS + O3 + 8) v152 j0 j72 j88 j104)
            (BD4 c4 bc4 (SS + O4 + pt4) (SS + O4) jp) ->
    0 <= q1 -> 0 <= q2 -> 0 <= q3 -> 0 <= q4 <= dcap ->
    0 <= pt1 -> (pt1 = 0 \/ pt1 + 8 <= L1) -> 0 <= pt2 -> (pt2 = 0 \/ pt2 + 8 <= L2) ->
    0 <= pt3 -> (pt3 = 0 \/ pt3 + 8 <= L3) -> 0 <= pt4 -> (pt4 = 0 \/ pt4 + 8 <= L4) ->
    0 <= bits1 < 2^64 -> 0 <= v152 < 2^64 -> 0 <= bits3 < 2^64 -> 0 <= bc4 < 2^32 ->
    DST + q1 < 2^64 -> DST + q2 < 2^64 -> DST + q3 < 2^64 ->
    evt psegs POST (MS (mkR xra (Z_to_bv 64 (SP + -416)) gp tp (Z_to_bv 64 (DST + q1)) t1 t2
                           (Z_to_bv 64 (SS + 6)) (Z_to_bv 64 (SS + O2)) (Z_to_bv 64 (DST + SEG)) a1 (Z_to_bv 64 (DST + q4))
                           (Z_to_bv 64 bits1) a4 (Z_to_bv 64 (DST + q3)) a6 (Z_to_bv 64 (DST + q2)) (Z_to_bv 64 (DT + 4)) x19
                           (Z_to_bv 64 DST) (Z_to_bv 64 (SS + O2 + pt2)) (Z_to_bv 64 bits3) (Z_to_bv 64 (SS + O3 + pt3))
                           (Z_to_bv 64 (SS + 6 + pt1)) (Z_to_bv 64 SEG) x26 x27 t3 t4 t5 t6)
                       F (Z_to_bv 64 0x19cc4) fc None mm (seg_rom psegs)).
